function uid(){ return typeof crypto!=='undefined'&&typeof crypto.randomUUID==='function'?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2); }
function clone(v){ return JSON.parse(JSON.stringify(v)); }
function readPreference(key){ try{return localStorage.getItem(key);}catch{return null;} }
function loadState(){
  try { const raw=localStorage.getItem(STORAGE_KEY); return normalizeState(raw?JSON.parse(raw):clone(seed)); }
  catch { return normalizeState(clone(seed)); }
}
function saveState(){ localStorage.setItem(STORAGE_KEY,JSON.stringify(state)); }
function today(){ const d=new Date(); return localDate(d); }
function localDate(d){ return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }
function addDays(date,days){ const d=parseLocalDate(date)||new Date(); d.setDate(d.getDate()+days); return localDate(d); }
function parseLocalDate(s){ if(!s)return null; const [y,m,d]=s.split('-').map(Number); return new Date(y,m-1,d); }
function currentMonth(){ return today().slice(0,7); }
function escapeHtml(s=''){ return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c])); }
function formatDate(s){ if(!s)return'—'; const [y,m,d]=s.split('-'); return `${d}.${m}.${y}`; }
function formatPeriod(a,b){ return `${formatDate(a)} — ${formatDate(b)}`; }
function dateInRange(d,a,b){ return !!d && d>=a && d<=b; }
function rangesOverlap(a1,a2,b1,b2){ return a1<=b2 && b1<=a2; }
function projectByCode(code){ return state.projects.find(p=>p.code===code); }
function projectName(code){ const p=projectByCode(code); return p?`${p.code} ${p.name}`:code||'Без проекта'; }
function taskDirection(t){ return projectByCode(t?.projectCode)?.direction||''; }
function directionLabel(d){ return d||'Прочее'; }
function allDirections(){ return [...DIRECTIONS,'']; }
function getTask(id){ return state.tasks.find(t=>t.id===id); }
function taskUpdates(id){ return state.updates.filter(u=>u.taskId===id).sort((a,b)=>(b.date+b.createdAt).localeCompare(a.date+a.createdAt)); }
function isClosed(t){ return CLOSED_STATUSES.includes(t.status); }
function isActive(t){ return !isClosed(t); }
function daysFromToday(s){ const d=parseLocalDate(s); if(!d)return null; const n=parseLocalDate(today()); return Math.round((d-n)/86400000); }
function options(items,selected,blank='—'){ return (blank!==null?`<option value="">${blank}</option>`:'')+items.map(x=>`<option value="${escapeHtml(x)}" ${x===selected?'selected':''}>${escapeHtml(x)}</option>`).join(''); }
function statusBadge(v){ const map={'В работе':'blue','Запланировано':'gray','Ожидание':'amber','К согласованию':'purple','Заблокировано':'red','Завершено':'green','Провалено':'red'}; return `<span class="badge ${map[v]||'gray'}">${escapeHtml(v||'—')}</span>`; }
function priorityBadge(v){ const map={'Высокий':'red','Средний':'amber','Низкий':'gray'}; return v?`<span class="badge ${map[v]||'gray'}">${escapeHtml(v)}</span>`:'—'; }
function nextTaskId(projectCode){
  const prefix=projectCode||'TASK'; let max=0;
  state.tasks.filter(t=>t.id.startsWith(prefix+'-')).forEach(t=>{const m=t.id.match(/-(\d+)$/);if(m)max=Math.max(max,Number(m[1]));});
  return `${prefix}-${String(max+1).padStart(2,'0')}`;
}
function kpi(label,value,hint='',cls=''){ return `<div class="card kpi-card ${cls?'kpi-'+cls:''}"><div class="label">${escapeHtml(label)}</div><div class="value">${escapeHtml(value)}</div><div class="hint">${escapeHtml(hint)}</div></div>`; }
function isTaskRelevantInPeriod(t,from,to){
  if(dateInRange(t.createdAt,from,to)||dateInRange(t.completedAt,from,to)) return true;
  if(taskUpdates(t.id).some(u=>dateInRange(u.date,from,to))) return true;
  if(state.cycles.some(c=>c.taskIds?.includes(t.id)&&rangesOverlap(c.startDate,c.endDate,from,to))) return true;
  return isActive(t) && (!t.startDate||t.startDate<=to) && (!t.completedAt||t.completedAt>=from);
}
function tasksForPeriod(from,to){ return state.tasks.filter(t=>isTaskRelevantInPeriod(t,from,to)); }
function latestCrmOnOrBefore(date){ return [...state.crm].filter(c=>c.snapshotDate&&c.snapshotDate<=date).sort((a,b)=>b.snapshotDate.localeCompare(a.snapshotDate))[0]||null; }
function crmInRange(from,to){ return state.crm.filter(c=>c.snapshotDate&&dateInRange(c.snapshotDate,from,to)).sort((a,b)=>a.snapshotDate.localeCompare(b.snapshotDate)); }
function crmTotal(c){ if(!c)return null; const vals=CRM_STAGES.map(s=>c.stages?.[s]); if(vals.some(v=>v===''||v===null||v===undefined))return null; return vals.reduce((a,b)=>a+Number(b||0),0); }

